SET status = #{status}, updated_by = #{updatedBy,jdbcType=BIGINT}
WHERE id = #{id} AND version = #{version}

UPDATE qs__auth__app_authorization
SET updated_by = #{updatedBy,jdbcType=BIGINT}
WHERE id = #{id} AND version = #{version}

UPDATE qs__auth__app_authorization
SET app_key = #{appKey}, app_secret = #{appSecret}
WHERE id = #{id}

